// The HTTP node before this ran once per course and answers in the same
// order, so item i belongs to course i. The course is taken from there
// rather than from the answer, which does not carry it.
const courses = $('List courses').all();
const results = [];

$input.all().forEach((item, i) => {
  const course_id = courses[i]?.json?.course_id;
  if (!course_id) return;

  const groups = item.json?.data?.Aggregate?.ChatHistory || [];
  for (const g of groups) {
    const user_id = g.groupedBy?.value;
    if (!user_id) continue;

    results.push({ json: {
      course_id,
      user_id,
      // Both halves of the key. Filtering on the learner alone returns
      // whichever course's record Weaviate finds first, and limit: 1 makes
      // that silent.
      um_query_body: {
        query: `{ Get { UserMemory(
          where: { operator: And operands: [
            { path: ["user_id"]   operator: Equal valueText: ${JSON.stringify(String(user_id))} }
            { path: ["course_id"] operator: Equal valueText: ${JSON.stringify(String(course_id))} }
          ] }
          limit: 1
        ) { _additional { id } user_id course_id concepts_mastered concepts_struggling open_questions learning_patterns summary last_updated chapter } } }`
      }
    }});
  }
});

return results;

const response = $input.item.json;
const { user_id, course_id } = $('Extract user_ids').item.json;
const memData = response?.data?.Get?.UserMemory || [];

let memory_id = null;
let last_updated = '1970-01-01T00:00:00.000Z';
let existing = {
  concepts_mastered: [],
  concepts_struggling: [],
  open_questions: [],
  learning_patterns: '',
  summary: ''
};

if (memData.length > 0) {
  const mem = memData[0];
  memory_id = mem._additional?.id || null;
  last_updated = mem.last_updated || '1970-01-01T00:00:00.000Z';
  existing = {
    concepts_mastered: mem.concepts_mastered || [],
    concepts_struggling: mem.concepts_struggling || [],
    open_questions: mem.open_questions || [],
    learning_patterns: mem.learning_patterns || '',
    summary: mem.summary || ''
  };
}

// The cursor is per course as well. Without that, a learner active in one
// course would move the cursor past the other course's messages, which are
// then never summarised.
const ch_query_body = {
  query: `{ Get { ChatHistory(
    where: { operator: And operands: [
      { path: ["user_id"]   operator: Equal valueText: ${JSON.stringify(String(user_id ?? ''))} }
      { path: ["course_id"] operator: Equal valueText: ${JSON.stringify(String(course_id ?? ''))} }
      { path: ["timestamp"] operator: GreaterThan valueText: ${JSON.stringify(String(last_updated ?? ''))} }
    ] }
    sort: [{ path: ["timestamp"] order: asc }]
    limit: 500
  ) { user_id course_id role text timestamp chapter concepts_mentioned } } }`
};

return {
  json: {
    user_id,
    course_id,
    memory_id,
    last_updated,
    existing,
    ch_query_body
  }
};

const response = $input.item.json;
const vars = $('Process Memory').item.json;
const { user_id, course_id, memory_id, existing } = vars;
const chatData = response?.data?.Get?.ChatHistory || [];

// [A] Keine neuen Messages
if (chatData.length === 0) {
  return { json: { skip: true, reason: 'no_new_messages', user_id, course_id } };
}

// [B] Session noch aktiv (< 30 Min Inaktivität)
const timestamps = chatData.map(m => new Date(m.timestamp).getTime());
const maxTimestamp = Math.max(...timestamps);
const diffMin = (Date.now() - maxTimestamp) / 60000;
if (diffMin < 30) {
  return { json: { skip: true, reason: 'session_active', user_id, course_id, inactive_min: Math.round(diffMin) } };
}

const maxChapter = Math.max(...chatData.map(m => m.chapter || 0));

const messagesText = chatData
  .map(m => m.role === 'user'
    ? `[user]: ${m.text}`
    : `[assistant]: ${m.text.slice(0, 200)}`)
  .join('\n');

return {
  json: {
    skip: false,
    user_id,
    course_id,
    memory_id,
    existing,
    max_chapter: maxChapter,
    last_updated_now: new Date().toISOString(),
    messagesText
  }
};

const response = $input.item.json;
const vars = $('Check and Prepare').item.json;
const { user_id, course_id, memory_id, existing, max_chapter, last_updated_now } = vars;

// Refused rather than written with an empty course. A record nobody can
// retrieve is a bug that hides; one written under the wrong course is a
// bug that shows up as another course's learner data.
if (!course_id) {
  return { json: { parse_error: true, error_reason: 'no_course', user_id,
                   memory_id, raw_preview: '' } };
}

// OpenAI-compatible chat/completions shape, which is what every provider
// this project supports speaks. The node before this was an Anthropic node
// with a hard-coded model, so on an installation configured for any other
// provider it could not run at all — and the parser read content[0].text,
// which only Anthropic returns.
const raw = response?.choices?.[0]?.message?.content || '';

// Thinking-Tags entfernen (falls Modell trotzdem denkt)
const cleaned = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

// JSON extrahieren
const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  return {
    json: {
      parse_error: true,
      error_reason: 'no_json_found',
      user_id,
      memory_id,
      raw_preview: raw.substring(0, 300)
    }
  };
}

let parsed;
try {
  parsed = JSON.parse(jsonMatch[0]);
} catch(e) {
  return {
    json: {
      parse_error: true,
      error_reason: 'json_parse_failed',
      user_id,
      memory_id,
      error: e.message,
      raw_preview: cleaned.substring(0, 300)
    }
  };
}

// REPLACE: concepts_mastered (nur aktuelle Session, max. 5)
const newMastered = parsed.concepts_mastered || [];

// REPLACE: concepts_struggling (nur aktuelle Session, max. 5), REMOVE wenn auch in mastered
const newStruggling = (parsed.concepts_struggling || [])
  .filter(c => !newMastered.includes(c));

// open_questions: REPLACE (aktuelle Session)
const newOpenQuestions = parsed.open_questions || [];

// learning_patterns: LLM konsolidiert (REPLACE, enthält Historie)
const newLearningPatterns = parsed.learning_patterns || existing.learning_patterns || '';

// summary: REPLACE (aktuelle Session)
const newSummary = parsed.summary || '';

return {
  json: {
    parse_error: false,
    user_id,
    memory_id,
    weaviate_object: {
      class: 'UserMemory',
      properties: {
        // The course this record belongs to, carried down from the loop
        // rather than read from the environment. The environment holds
        // the installation's single course, which is exactly what stopped
        // there being more than one.
        course_id,
        user_id,
        concepts_mastered: newMastered,
        concepts_struggling: newStruggling,
        open_questions: newOpenQuestions,
        learning_patterns: newLearningPatterns,
        summary: newSummary,
        chapter: max_chapter || 0,
        last_updated: last_updated_now
      }
    }
  }
};

const response = $input.item.json;
const mergeVars = $('Parse and Merge').item.json;
const { user_id, memory_id } = mergeVars;

if (!response?.id) {
  return {
    json: {
      post_ok: false,
      user_id,
      error: 'POST to Weaviate returned no ID',
      response_preview: JSON.stringify(response).substring(0, 200)
    }
  };
}

return {
  json: {
    post_ok: true,
    user_id,
    new_object_id: response.id,
    old_memory_id: memory_id
  }
};

