// One record per learner per course, so the loop has to run over courses
// first. It used to run over learners alone: a learner in two courses got a
// single record in which both courses' concepts were merged, and it was
// written with the installation's single course from the environment.
const groups = $input.first().json?.data?.Aggregate?.ChatHistory || [];
const out = [];

for (const g of groups) {
  const course_id = g.groupedBy?.value;
  // Messages written before the sync carried the course have an empty one.
  // They are left out rather than folded into whichever course comes first:
  // a learning record is about one course, and a wrong one is invisible.
  if (!course_id) continue;

  out.push({ json: {
    course_id,
    users_query_body: {
      query: `{ Aggregate { ChatHistory(
        where: { path: ["course_id"] operator: Equal valueText: ${JSON.stringify(String(course_id))} }
        groupBy: "user_id"
      ) { groupedBy { value } meta { count } } } }`
    }
  }});
}

if (out.length === 0) {
  console.log('No course has any chat history yet — nothing to summarise.');
}
return out;
